  "landing.hero.h1": "\u0aa4\u0aae\u0abe\u0ab0\u0abe \u0ab5\u0acd\u0aaf\u0ab5\u0ab8\u0abe\u0aaf \u0aae\u0abe\u0a9f\u0ac7 \u0aaf\u0acb\u0a97\u0acd\u0aaf \u0ab8\u0ab0\u0a95\u0abe\u0ab0\u0ac0 \u0aaf\u0acb\u0a9c\u0aa8\u0abe\u0a93 \u0ab6\u0acb\u0aa7\u0acb",
  "landing.hero.h1.accent": "\u0ab5\u0acd\u0aaf\u0ab5\u0ab8\u0abe\u0aaf",
  "landing.hero.sub": "VittVanni \u0aad\u0abe\u0ab0\u0aa4\u0aa8\u0ac0 \u0a95\u0ac7\u0aa8\u0acd\u0aa6\u0acd\u0ab0 \u0a85\u0aa8\u0ac7 \u0ab0\u0abe\u0a9c\u0acd\u0aaf \u0ab8\u0ab0\u0a95\u0abe\u0ab0\u0aa8\u0ac0 \u0aaf\u0acb\u0a9c\u0aa8\u0abe\u0a93\u0aa8\u0ac7 \u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0acb\u0aab\u0abe\u0a87\u0ab2 \u0ab8\u0abe\u0aa5\u0ac7 \u0aae\u0ac7\u0ab3\u0ab5\u0ac7 \u0a9b\u0ac7 \u2014 \u0ab8\u0abe\u0aa6\u0ac0 \u0a97\u0ac1\u0a9c\u0ab0\u0abe\u0aa4\u0ac0, \u0aaa\u0a97\u0ab2\u0ac1\u0a82-\u0aa6\u0ab0-\u0aaa\u0a97\u0ab2\u0ac1\u0a82.",
  "landing.hero.cta": "\u0aae\u0ac7\u0a9a \u0a95\u0ab0\u0ab5\u0abe\u0aa8\u0ac1\u0a82 \u0ab6\u0ab0\u0ac2 \u0a95\u0ab0\u0acb",
  "landing.hero.cta2": "\u0a86 \u0a95\u0ac7\u0ab5\u0ac0 \u0ab0\u0ac0\u0aa4\u0ac7 \u0a95\u0abe\u0aae \u0a95\u0ab0\u0ac7 \u0a9b\u0ac7",
  "landing.how.title": "\u0a86 \u0a95\u0ac7\u0ab5\u0ac0 \u0ab0\u0ac0\u0aa4\u0ac7 \u0a95\u0abe\u0aae \u0a95\u0ab0\u0ac7 \u0a9b\u0ac7",
  "landing.how.1.title": "\u0aa4\u0aae\u0abe\u0ab0\u0abe \u0ab5\u0abf\u0ab6\u0ac7 \u0a95\u0ab9\u0acb",
  "landing.how.1.text": "\u0aa4\u0aae\u0abe\u0ab0\u0abe \u0ab5\u0acd\u0aaf\u0ab5\u0ab8\u0abe\u0aaf, \u0ab8\u0acd\u0aa5\u0ab3 \u0a85\u0aa8\u0ac7 \u0aaa\u0abe\u0ab0\u0acd\u0ab6\u0acd\u0ab5\u0aad\u0ac2\u0aae\u0abf \u0ab5\u0abf\u0ab6\u0ac7 9 \u0ab8\u0ab0\u0ab3 \u0aaa\u0acd\u0ab0\u0ab6\u0acd\u0aa8\u0acb\u0aa8\u0abe \u0a9c\u0ab5\u0abe\u0aac \u0a86\u0aaa\u0acb.",
  "landing.how.2.title": "\u0a85\u0aae\u0ac7 \u0aa4\u0aae\u0aa8\u0ac7 \u0aae\u0ac7\u0ab3\u0ab5\u0ac0\u0a8f \u0a9b\u0ac0\u0a8f",
  "landing.how.2.text": "\u0a85\u0aae\u0abe\u0ab0\u0ac0 \u0ab8\u0abf\u0ab8\u0acd\u0a9f\u0aae \u0aa4\u0aae\u0abe\u0ab0\u0abe \u0a9c\u0ab5\u0abe\u0aac\u0acb\u0aa5\u0ac0 14 \u0a95\u0acd\u0ab7\u0ac7\u0aa4\u0acd\u0ab0\u0acb\u0aae\u0abe\u0a82 90+ \u0aaf\u0acb\u0a9c\u0aa8\u0abe\u0a93\u0aa8\u0ac7 \u0a95\u0acd\u0ab0\u0aae \u0a86\u0aaa\u0ac7 \u0a9b\u0ac7.",
  "landing.how.3.title": "\u0ab8\u0aae\u0a9c\u0ac2\u0aa4\u0ac0 \u0aae\u0ac7\u0ab3\u0ab5\u0acb",
  "landing.how.3.text": "\u0aa6\u0ab0\u0ac7\u0a95 \u0aaf\u0acb\u0a9c\u0aa8\u0abe \u0ab6\u0abe \u0aae\u0abe\u0a9f\u0ac7 \u0aac\u0a82\u0aa7\u0aac\u0ac7\u0ab8\u0ac7 \u0a9b\u0ac7 \u0aa4\u0ac7\u0aa8\u0abe\u0a82 \u0ab8\u0acd\u0aaa\u0ab7\u0acd\u0a9f \u0a95\u0abe\u0ab0\u0aa3\u0acb \u2014 \u0a9c\u0a9f\u0abf\u0ab2 \u0ab6\u0aac\u0acd\u0aa6\u0acb \u0ab5\u0a97\u0ab0.",
  "landing.how.4.title": "\u0a86\u0aa4\u0acd\u0aae\u0ab5\u0abf\u0ab6\u0acd\u0ab5\u0abe\u0ab8\u0aa5\u0ac0 \u0a85\u0ab0\u0a9c\u0ac0 \u0a95\u0ab0\u0acb",
  "landing.how.4.text": "\u0aa6\u0ab8\u0acd\u0aa4\u0abe\u0ab5\u0ac7\u0a9c\u0acb, \u0aa4\u0abe\u0ab0\u0ac0\u0a96\u0acb \u0a85\u0aa8\u0ac7 \u0a85\u0aa0\u0ab5\u0abe\u0aa1\u0abf\u0a95 \u0a85\u0ab0\u0a9c\u0ac0\u0aa8\u0acb \u0ab0\u0acb\u0aa1\u0aae\u0ac7\u0aaa \u0aae\u0ac7\u0ab3\u0ab5\u0acb.",
  "landing.stats.title": "\u0a86\u0a97\u0ab3 \u0ab5\u0aa7\u0aa4\u0abe \u0a89\u0aa6\u0acd\u0aaf\u0acb\u0a97\u0ab8\u0abe\u0ab9\u0ab8\u0abf\u0a95\u0acb\u0aa8\u0acb \u0ab5\u0abf\u0ab6\u0acd\u0ab5\u0abe\u0ab8",
  "landing.stats.schemes": "\u0a86\u0ab5\u0ab0\u0ac0 \u0ab2\u0ac7\u0ab5\u0abe\u0aaf\u0ac7\u0ab2\u0ac0 \u0aaf\u0acb\u0a9c\u0aa8\u0abe\u0a93",
  "landing.stats.sectors": "\u0ab5\u0acd\u0aaf\u0ab5\u0ab8\u0abe\u0aaf \u0a95\u0acd\u0ab7\u0ac7\u0aa4\u0acd\u0ab0\u0acb",
  "landing.stats.states": "\u0a86\u0ab5\u0ab0\u0ac0 \u0ab2\u0ac7\u0ab5\u0abe\u0aaf\u0ac7\u0ab2\u0abe\u0a82 \u0ab0\u0abe\u0a9c\u0acd\u0aaf\u0acb",
  "landing.stats.languages": "\u0aad\u0abe\u0ab7\u0abe\u0a93",
  "landing.features.title": "\u0a96\u0ab0\u0abe \u0a89\u0aa6\u0acd\u0aaf\u0acb\u0a97\u0ab8\u0abe\u0ab9\u0ab8\u0abf\u0a95\u0acb \u0aae\u0abe\u0a9f\u0ac7 \u0aac\u0aa8\u0abe\u0ab5\u0ac7\u0ab2\u0ac1\u0a82",
  "landing.features.1.title": "પોર્ટલમાં અરજી કરો",
  "landing.features.1.text": "સરકારી સાઇટ્સ પર ભટકવું નહીં — અહીં જ અરજી, ટ્રેક અને ચેટ કરો.",
  "landing.features.2.title": "23 \u0aad\u0abe\u0ab7\u0abe\u0a93",
  "landing.features.2.text": "\u0a89\u0aaa\u0ab0\u0aa8\u0abe \u0aae\u0ac7\u0aa8\u0ac2\u0aae\u0abe\u0a82\u0aa5\u0ac0 \u0a95\u0acb\u0a88\u0aaa\u0aa3 \u0aad\u0abe\u0ab0\u0aa4\u0ac0\u0aaf \u0aad\u0abe\u0ab7\u0abe \u0aaa\u0ab8\u0a82\u0aa6 \u0a95\u0ab0\u0acb.",
  "landing.features.3.title": "\u0a91\u0aab\u0ab2\u0abe\u0a87\u0aa8-\u0a85\u0aa8\u0ac1\u0a95\u0ac2\u0ab3",
  "landing.features.3.text": "\u0aaf\u0acb\u0a9c\u0aa8\u0abe\u0a93 \u0ab2\u0acb\u0a95\u0ab2 \u0a95\u0ac7\u0ab6\u0aae\u0abe\u0a82 \u0ab0\u0ab9\u0ac7 \u0a9b\u0ac7, \u0aa4\u0ac7\u0aa5\u0ac0 \u0a87\u0aa8\u0acd\u0a9f\u0ab0\u0aa8\u0ac7\u0a9f \u0ab5\u0a97\u0ab0 \u0aaa\u0aa3 \u0a9c\u0acb\u0a88 \u0ab6\u0a95\u0abe\u0aaf \u0a9b\u0ac7.",
  "landing.features.4.title": "\u0a97\u0acb\u0aaa\u0aa8\u0ac0\u0aaf\u0aa4\u0abe\u0aa8\u0ac7 \u0aaa\u0acd\u0ab0\u0abe\u0aa5\u0aae\u0abf\u0a95\u0aa4\u0abe",
  "landing.features.4.text": "\u0aa4\u0aae\u0abe\u0ab0\u0acb \u0aa1\u0ac7\u0a9f\u0abe \u0aa4\u0aae\u0abe\u0ab0\u0acb \u0a9c \u0ab0\u0ab9\u0ac7 \u0a9b\u0ac7. \u0a95\u0acd\u0aaf\u0abe\u0ab0\u0ac7\u0aaf \u0ab5\u0ac7\u0a9a\u0abe\u0aa4\u0acb \u0aa8\u0aa5\u0ac0.",
